(() => {
    'use strict';

    const weekdays = '日一二三四五六';
    const chinese = '〇一二三四五六七八九';
    const dayMs = 86_400_000;
    const mod = (value, base) => ((value % base) + base) % base;
    const serial = (year, month, day) => Date.UTC(year, month - 1, day) / dayMs;
    const date = value => new Date(value * dayMs);
    const dateKey = (month, day) => month * 100 + day;

    // 节日使用每年实际纪念的月日或星期规则。国家与地区可按需要增删。
    const fixed = {
        101: '多国·元旦', 211: '日本·建国纪念日', 214: '多国·情人节',
        223: '日本·天皇诞生日', 301: '韩国·三一节', 308: '国际·国际妇女节',
        314: '日本/韩国·白色情人节', 322: '国际·世界水日', 422: '国际·世界地球日',
        429: '日本·昭和日', 501: '中国/法国·劳动节', 503: '日本·宪法纪念日',
        504: '日本·绿之日', 505: '日本/韩国·儿童节', 508: '法国·二战胜利纪念日',
        606: '韩国·显忠日', 614: '美国·国旗日', 619: '美国·六月节',
        701: '加拿大·加拿大日', 704: '美国·独立日', 714: '法国·国庆日',
        811: '日本·山之日', 815: '韩国·光复节', 930: '加拿大·真相与和解日',
        1001: '中国·国庆节', 1003: '韩国·开天节', 1009: '韩国·韩文日',
        1031: '多国·万圣夜', 1101: '法国·诸圣节', 1103: '日本·文化日',
        1111: '美国·退伍军人节|加拿大·阵亡将士纪念日|法国·停战纪念日',
        1123: '日本·勤劳感谢日', 1224: '多国·平安夜', 1225: '多国·圣诞节',
        1226: '英国/加拿大·节礼日', 1231: '多国·跨年夜',
    };
    // [月, 星期（周日为 0）, 第几次出现（-1 为最后一次）, 标签]
    const byWeekday = [
        [1, 1, 2, '日本·成人日'], [1, 1, 3, '美国·马丁·路德·金纪念日'],
        [2, 1, 3, '美国·华盛顿诞辰纪念日'], [5, 1, 1, '英格兰/威尔士·五月初银行假日'],
        [5, 0, 2, '多国·母亲节'], [5, 1, -1, '美国·阵亡将士纪念日'],
        [5, 1, -1, '英格兰/威尔士·春季银行假日'], [6, 0, 3, '多国·父亲节'],
        [7, 1, 3, '日本·海之日'], [8, 1, -1, '英格兰/威尔士·夏季银行假日'],
        [9, 1, 1, '美国/加拿大·劳动节'], [9, 1, 3, '日本·敬老日'],
        [10, 1, 2, '加拿大·感恩节'], [10, 1, 2, '日本·体育日'],
        [11, 4, 4, '美国·感恩节'],
    ];
    const lunarFestivals = {
        101: '中国·春节', 115: '中国·元宵节', 202: '中国·龙抬头', 303: '中国·上巳节',
        505: '中国·端午节', 707: '中国·七夕', 715: '中国·中元节', 815: '中国·中秋节',
        909: '中国·重阳节', 1015: '中国·下元节',
    };
    const terms = '立春 雨水 惊蛰 春分 清明 谷雨 立夏 小满 芒种 夏至 小暑 大暑 立秋 处暑 白露 秋分 寒露 霜降 立冬 小雪 大雪 冬至 小寒 大寒'.split(' ').join('|');
    const yearPattern = '(?:(?<year>[\\p{Script=Han}]{0,8}\\d{1,6})\\s*年\\s*)?';
    const monthPattern = '(?<month>\\d{1,2})\\s*月\\s*';
    const dayPattern = '(?<day>\\d{1,2})\\s*[日号](?!\\d)';
    const weekdayPattern = '(?:[ \\t·•、,]*(?:星期|礼拜|周)\\s*(?<weekday>[一二三四五六日天1-7]))?';
    const clockPattern = '(?:[ \\t·•、,]*(?<time>(?:[01]?\\d|2[0-3]):[0-5]\\d)(?!\\d))?';
    const starts = new RegExp(`(?<![\\d])${yearPattern}${monthPattern}${dayPattern}${weekdayPattern}${clockPattern}`, 'gu');
    const ends = new RegExp(`^[ \\t]*(?:—+|–|−|~|-|至|到)[ \\t]*${yearPattern}(?:${monthPattern})?${dayPattern}${weekdayPattern}${clockPattern}`, 'u');
    const lunarMonth = '(闰)?(正|一|二|三|四|五|六|七|八|九|十[一二]?|冬|腊)月';
    const lunarDay = '(初[一二三四五六七八九十]|十[一二三四五六七八九]?|二十[一二三四五六七八九]?|廿[一二三四五六七八九]?|三十)(?![一二三四五六七八九十月\\d])';
    const lunarStart = new RegExp(`(?:^|[·•,、;\\s(])(?:农历\\s*)?${lunarMonth}\\s*${lunarDay}`, 'u');
    const lunarEnd = new RegExp(`^\\s*(?:至|到|—+|–|-|~)\\s*(?:农历\\s*)?(?:${lunarMonth})?\\s*${lunarDay}`, 'u');
    const countdown = new RegExp(`(?:距(?:离)?|离)\\s*(${terms})\\s*(?:还)?(?:有|剩)?\\s*([\\d一二三四五六七八九十两]{1,3})\\s*天`, 'u');

    function chineseNumber(value) {
        if (/^\d+$/.test(value)) return Number(value);
        const plain = value.replace(/^初/, '').replace(/^廿/, '二十').replace(/两/g, '二');
        if (!plain.includes('十')) return chinese.indexOf(plain);
        const [ten, one] = plain.split('十');
        return (ten ? chinese.indexOf(ten) : 1) * 10 + (one ? chinese.indexOf(one) : 0);
    }

    function point(groups, fallbackMonth) {
        const { year, day, time } = groups;
        const month = Number(groups.month || fallbackMonth);
        const week = groups.weekday?.replace('天', '日');
        const weekday = week ? (/\d/.test(week) ? Number(week) % 7 : weekdays.indexOf(week)) : null;
        if (month < 1 || month > 12 || Number(day) < 1 || Number(day) > 31) return null;
        return { year, month, day: Number(day), weekday, time };
    }

    function era(label) {
        const parts = label?.match(/^(.*?)(\d+)$/u);
        return parts && { prefix: parts[1], number: Number(parts[2]), width: parts[2].length };
    }

    function placeRange(first, last) {
        const firstEra = era(first.year), lastEra = era(last.year);
        const wraps = dateKey(last.month, last.day) < dateKey(first.month, first.day);
        const hasBothYears = firstEra && lastEra && firstEra.prefix === lastEra.prefix;
        const offset = hasBothYears ? lastEra.number - firstEra.number : Number(wraps);
        if (offset < 0 || offset > 20 || (!offset && wraps)) return null;
        const endEra = lastEra && { ...lastEra, number: lastEra.number - offset };
        let fallback;
        // The internal Gregorian dates supply month lengths only. Weekdays
        // always come from the story, with a constant shift over the range.
        for (let year = 2001; year <= 2400; year++) {
            const start = serial(year, first.month, first.day);
            const end = serial(year + offset, last.month, last.day);
            if (date(start).getUTCMonth() + 1 !== first.month || date(end).getUTCMonth() + 1 !== last.month) continue;
            const shift = first.weekday === null ? last.weekday - date(end).getUTCDay() : first.weekday - date(start).getUTCDay();
            const conflict = last.weekday !== null && mod(date(end).getUTCDay() + shift, 7) !== last.weekday;
            const range = { first, last, start, end, shift, year, era: firstEra || endEra, conflict };
            if (!conflict) return range;
            fallback ??= range;
        }
        return fallback;
    }

    function addLunar(range, tail) {
        const first = lunarStart.exec(tail);
        if (!first) return [];
        const following = tail.slice(first.index + first[0].length);
        const last = lunarEnd.exec(following);
        const anchor = (match, value) => {
            const [, leap, month, day] = match;
            const label = month || first[2];
            return { value, leap: month ? !!leap : !!first[1], month: chineseNumber(label.replace('正', '一').replace('冬', '十一').replace('腊', '十二')), day: chineseNumber(day) };
        };
        // A lone lunar date after a range refers to its end. A lunar range
        // supplies a separate anchor for each endpoint.
        return last && range.start !== range.end ? [anchor(first, range.start), anchor(last, range.end)] : [anchor(last || first, range.end)];
    }

    function parse(text) {
        const source = text.normalize('NFKC');
        let scene, consumed = 0;
        for (const match of source.matchAll(starts)) {
            if (match.index < consumed) continue;
            const first = point(match.groups);
            if (!first) continue;
            const next = match.index + match[0].length;
            const endMatch = ends.exec(source.slice(next));
            const fallbackMonth = Number(endMatch?.groups.day) < first.day ? first.month % 12 + 1 : first.month;
            const last = endMatch ? point(endMatch.groups, fallbackMonth) : first;
            if (!last || (first.weekday === null && last.weekday === null)) continue;
            const range = placeRange(first, last);
            if (!range) continue;
            consumed = next + (endMatch?.[0].length || 0);
            const tail = source.slice(consumed, consumed + 320).split(/[\r\n」』<]/u, 1)[0];
            const termMatch = countdown.exec(tail);
            const termDays = termMatch && chineseNumber(termMatch[2]);
            const term = termMatch && termDays >= 0 && termDays <= 366 ? { value: range.end + termDays, name: termMatch[1] } : null;
            scene = { ...range, lunar: addLunar(range, tail), term };
        }
        return scene;
    }

    const weekOf = (value, scene) => mod(date(value).getUTCDay() + scene.shift, 7);
    const sameLunar = (a, b) => a.month === b.month && a.leap === b.leap && a.day === b.day;
    const lunarFor = (scene, value) => {
        const anchors = scene.lunar;
        const exact = anchors.find(item => item.value === value);
        if (exact) return exact;
        const dayOne = item => item.value - item.day + 1;
        if (anchors.length === 2 && anchors[0].month === anchors[1].month && anchors[0].leap === anchors[1].leap && dayOne(anchors[0]) !== dayOne(anchors[1])) return null;
        const possible = anchors.map(anchor => ({ ...anchor, day: value - dayOne(anchor) + 1 })).filter(item => item.day >= 1 && item.day <= 29);
        return possible.length && possible.every(item => sameLunar(item, possible[0])) ? possible[0] : null;
    };

    function lunarLabel(lunar) {
        const month = ['正', '二', '三', '四', '五', '六', '七', '八', '九', '十', '十一', '腊'][lunar.month - 1];
        const day = lunar.day;
        const text = day <= 10 ? `初${day === 10 ? '十' : chinese[day]}` : ({ 20: '二十', 30: '三十' }[day] || `${day < 20 ? '十' : '廿'}${chinese[day % 10]}`);
        return `${lunar.leap ? '闰' : ''}${month}月${text}`;
    }

    function holidays(value, scene, lunar) {
        const current = date(value), month = current.getUTCMonth() + 1, day = current.getUTCDate();
        const items = fixed[dateKey(month, day)]?.split('|') || [];
        const weekday = weekOf(value, scene), week = Math.ceil(day / 7);
        const isLast = date(value + 7).getUTCMonth() !== current.getUTCMonth();
        for (const [m, w, nth, label] of byWeekday) {
            if (m === month && w === weekday && (nth === -1 ? isLast : nth === week)) items.push(label);
        }
        const lunarFestival = lunar && !lunar.leap && lunarFestivals[dateKey(lunar.month, lunar.day)];
        if (lunarFestival) items.unshift(lunarFestival);
        if (scene.term?.value === value) items.unshift(`节气·${scene.term.name}`);
        return items;
    }

    function monthDays(month, scene) {
        const end = serial(date(month).getUTCFullYear(), date(month).getUTCMonth() + 2, 1);
        const start = month - (mod(weekOf(month, scene) - 1, 7) || 7);
        const stop = end + (mod(1 - weekOf(end, scene), 7) || 7);
        return Array.from({ length: stop - start }, (_, index) => start + index);
    }

    const monthOf = (value, step = 0) => {
        const current = date(value);
        return serial(current.getUTCFullYear(), current.getUTCMonth() + 1 + step, 1);
    };

    function fullDate(value, scene, time) {
        const current = date(value);
        return `${current.getUTCMonth() + 1}月${current.getUTCDate()}日 周${weekdays[weekOf(value, scene)]}${time ? ` ${time}` : ''}`;
    }

    const eraLabel = (value, scene) => scene.era ? `${scene.era.prefix}${String(scene.era.number + date(value).getUTCFullYear() - scene.year).padStart(scene.era.width, '0')}年` : '';
    const node = (tag, className, label) => {
        const element = document.createElement(tag);
        if (className) element.className = className;
        if (label) element.textContent = label;
        return element;
    };

    const style = node('style');
    style.textContent = `
        .plot-calendar { --ink:#2d3831; --quiet:#5b645a; --line:#d5d7c9; --paper:#fcfaf3; --range:#dce8d8; --accent:#255440;
            position:fixed; right:12px; top:66px; z-index:20000; width:min(385px, calc(100vw - 24px)); max-height:calc(100dvh - 78px);
            box-sizing:border-box; overflow:auto; color:var(--ink); background:var(--paper); border:1px solid var(--line);
            border-radius:14px; box-shadow:0 8px 26px #1e2b242e; font:14px/1.45 system-ui, sans-serif; }
        .plot-calendar[hidden], .plot-calendar [hidden] { display:none!important; }
        .plot-calendar.is-collapsed { width:42px; overflow:visible; border:0; border-radius:0; background:transparent; box-shadow:none; }
        .plot-calendar button { color:inherit; font:inherit; cursor:pointer; -webkit-tap-highlight-color:transparent; }
        .plot-calendar button:focus-visible { outline:2px solid var(--accent); outline-offset:-2px; }
        .plot-calendar .toggle { position:sticky; top:0; z-index:1; width:42px; height:42px; margin-left:auto;
            display:grid; place-items:center; padding:0; border:0; border-radius:10px; background:var(--paper); }
        .plot-calendar.is-collapsed .toggle { border:1px solid var(--line); }
        .plot-calendar .toggle:hover { background:#ebe0cf; }
        .plot-calendar .toggle[aria-expanded=true] { color:#805b40; background:#eae2d5; }
        .plot-calendar .toggle svg { display:block; width:20px; height:20px; }
        .plot-calendar .content { padding:0 12px 12px; }
        .plot-calendar .range { margin:0 0 8px; color:var(--quiet); font-size:12px; }
        .plot-calendar .nav { display:flex; align-items:center; justify-content:space-between; border-top:1px solid var(--line); padding-top:4px; gap:3px; }
        .plot-calendar .nav button { min-height:42px; min-width:42px; border:0; background:transparent; border-radius:8px; }
        .plot-calendar .nav button:hover, .plot-calendar .day:hover { background:#e9ede2; }
        .plot-calendar .nav .month { font-weight:700; padding:0 4px; }
        .plot-calendar .grid { display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); gap:2px; }
        .plot-calendar .weekday { color:var(--quiet); font-size:12px; text-align:center; padding:5px 0; }
        .plot-calendar .day { min-height:43px; min-width:0; padding:2px; display:grid; align-content:start; justify-items:center;
            gap:0; border:1px solid transparent; border-radius:7px; background:transparent; line-height:1.3; }
        .plot-calendar .outside { color:var(--quiet); }
        .plot-calendar .in-range { background:var(--range); color:var(--accent); }
        .plot-calendar .endpoint { font-weight:750; }
        .plot-calendar .day[aria-pressed=true] { border-color:var(--accent); }
        .plot-calendar .sub { display:block; max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:12px; }
        .plot-calendar .holiday { color:#8f3f31; }
        .plot-calendar .detail { min-height:38px; margin-top:7px; padding:8px 2px 0; border-top:1px solid var(--line); font-size:12px; }
        .plot-calendar .detail strong { display:block; margin-bottom:3px; }
        .plot-calendar .detail ul { padding-left:18px; margin:3px 0 0; }
        .plot-calendar .warning { margin:4px 0 7px; color:#8f3f31; font-size:12px; }
        @media(max-width:380px) { .plot-calendar { right:6px; width:calc(100vw - 12px); } .plot-calendar .content { padding-inline:8px; } }
    `;
    document.head.append(style);

    const panel = node('section', 'plot-calendar');
    panel.setAttribute('aria-label', '剧情日历');
    panel.hidden = true;
    const toggle = node('button', 'toggle');
    toggle.type = 'button';
    const svgNamespace = 'http://www.w3.org/2000/svg';
    const toggleIcon = document.createElementNS(svgNamespace, 'svg');
    for (const [key, value] of Object.entries({ viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': '2', 'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true' })) {
        toggleIcon.setAttribute(key, value);
    }
    // Calendar outline from Tabler Icons, v3.46.0. MIT, copyright (c) 2020-2026 Paweł Kuna.
    // https://github.com/tabler/tabler-icons/blob/v3.46.0/LICENSE
    for (const path of ["M4 7a2 2 0 0 1 2 -2h12a2 2 0 0 1 2 2v12a2 2 0 0 1 -2 2h-12a2 2 0 0 1 -2 -2v-12","M16 3v4","M8 3v4","M4 11h16","M11 15h1","M12 15v3"]) {
        const element = document.createElementNS(svgNamespace, 'path');
        element.setAttribute('d', path);
        toggleIcon.append(element);
    }
    toggle.append(toggleIcon);
    const content = node('div', 'content');
    content.id = 'plot-calendar-content';
    toggle.setAttribute('aria-controls', content.id);
    const rangeText = node('p', 'range'), warning = node('p', 'warning');
    const nav = node('div', 'nav');
    const previous = node('button', '', '‹'), next = node('button', '', '›'), monthTitle = node('button', 'month');
    previous.setAttribute('aria-label', '上个月');
    next.setAttribute('aria-label', '下个月');
    monthTitle.setAttribute('title', '回到剧情日期');
    nav.append(previous, monthTitle, next);
    const grid = node('div', 'grid');
    const detail = node('div', 'detail');
    detail.setAttribute('aria-live', 'polite');
    content.append(rangeText, warning, nav, grid, detail);
    panel.append(toggle, content);
    document.body.append(panel);

    let scene, sceneKey, displayedMonth, selected, expanded = false;
    const cachedReplies = new Map();

    function setExpanded(value) {
        expanded = value;
        content.hidden = !expanded;
        toggle.setAttribute('aria-expanded', String(expanded));
        panel.classList.toggle('is-collapsed', !expanded);
        const label = expanded ? '收起剧情日历' : '展开剧情日历';
        toggle.setAttribute('aria-label', label);
        toggle.title = label;
    }

    function renderDetail() {
        const lunar = lunarFor(scene, selected);
        const entries = holidays(selected, scene, lunar);
        const times = [...new Set([
            selected === scene.start && scene.first.time,
            selected === scene.end && scene.last.time,
        ].filter(Boolean))];
        const heading = [eraLabel(selected, scene) + fullDate(selected, scene), times.join('–'), lunar && lunarLabel(lunar)].filter(Boolean).join(' · ');
        detail.replaceChildren(node('strong', '', heading));
        if (entries.length) {
            const list = node('ul');
            list.append(...entries.map(label => node('li', '', label)));
            detail.append(list);
        }
    }

    function renderMonth() {
        const current = date(displayedMonth);
        monthTitle.textContent = `${eraLabel(displayedMonth, scene)}${current.getUTCMonth() + 1}月`;
        monthTitle.setAttribute('aria-label', `${monthTitle.textContent}，回到剧情日期`);
        grid.replaceChildren(...[...'一二三四五六日'].map(label => node('div', 'weekday', label)));
        for (const value of monthDays(displayedMonth, scene)) {
            const day = date(value), lunar = lunarFor(scene, value), entries = holidays(value, scene, lunar);
            const button = node('button', 'day');
            button.classList.toggle('outside', day.getUTCMonth() !== current.getUTCMonth());
            button.classList.toggle('in-range', value >= scene.start && value <= scene.end);
            button.classList.toggle('endpoint', value === scene.start || value === scene.end);
            button.setAttribute('aria-pressed', String(value === selected));
            const label = [eraLabel(value, scene) + fullDate(value, scene), lunar && lunarLabel(lunar), ...entries].filter(Boolean).join('，');
            button.title = label;
            button.setAttribute('aria-label', label);
            button.append(node('span', '', String(day.getUTCDate())));
            const short = entries[0]?.split('·').slice(1).join('·') || (lunar && lunarLabel(lunar).replace(/^.*月/, ''));
            if (short) button.append(node('span', entries.length ? 'sub holiday' : 'sub', short));
            button.onclick = () => {
                grid.querySelector('[aria-pressed="true"]')?.setAttribute('aria-pressed', 'false');
                selected = value;
                button.setAttribute('aria-pressed', 'true');
                renderDetail();
            };
            grid.append(button);
        }
        renderDetail();
    }

    function goToMonth(value) {
        displayedMonth = value;
        selected = monthOf(scene.end) === value ? scene.end : value;
        renderMonth();
    }

    function refresh() {
        const chat = SillyTavern.getContext().chat;
        const from = Math.max(0, chat.length - 40);
        for (const i of cachedReplies.keys()) if (i < from || i >= chat.length) cachedReplies.delete(i);
        let found;
        for (let i = chat.length - 1; i >= from; i--) {
            const reply = chat[i];
            if (!reply || reply.is_user || reply.is_system || reply.textAvailable === false || typeof reply.mes !== 'string' || !reply.mes) continue;
            const prior = cachedReplies.get(i);
            const entry = prior?.text === reply.mes ? prior : { text: reply.mes, scene: parse(reply.mes) };
            cachedReplies.set(i, entry);
            if (entry.scene) { found = entry.scene; break; }
        }
        const key = JSON.stringify(found);
        if (key === sceneKey) return;
        sceneKey = key;
        scene = found;
        panel.hidden = !scene;
        if (!scene) return;
        const first = eraLabel(scene.start, scene) + fullDate(scene.start, scene, scene.first.time);
        const last = (date(scene.start).getUTCFullYear() !== date(scene.end).getUTCFullYear() ? eraLabel(scene.end, scene) : '') + fullDate(scene.end, scene, scene.last.time);
        rangeText.textContent = scene.start === scene.end && scene.first.time === scene.last.time ? first : `${first} → ${last}`;
        warning.hidden = !scene.conflict;
        if (scene.conflict) warning.textContent = `回复给出的结束星期为周${weekdays[scene.last.weekday]}，与起点不一致。日历按起点星期排列。`;
        setExpanded(expanded);
        goToMonth(monthOf(scene.end));
    }

    toggle.onclick = () => setExpanded(!expanded);
    previous.onclick = () => goToMonth(monthOf(displayedMonth, -1));
    next.onclick = () => goToMonth(monthOf(displayedMonth, 1));
    monthTitle.onclick = () => goToMonth(monthOf(scene.end));
    panel.addEventListener('keydown', event => {
        if (expanded && event.key === 'Escape') { setExpanded(false); toggle.focus(); }
    });
    for (const name of ['MESSAGE_RECEIVED', 'GENERATION_ENDED', 'MESSAGE_EDITED', 'MESSAGE_SWIPED', 'MESSAGE_DELETED', 'CHAT_CHANGED']) {
        if (window.tavern_events?.[name]) eventOn(window.tavern_events[name], refresh);
    }
    // In 酒馆伴侣, some branch edits arrive as silent snapshot refreshes.
    // Poll the in-memory chat only, and parse each reply once per text revision.
    setInterval(refresh, 800);
    setExpanded(false);
    refresh();
})();
